          "investigations": "<div class=\"lab-table\"><div class=\"lab-row lab-head\"><span>Εξέταση</span><span>Τιμή</span><span>Φυσιολογικό εύρος</span><span>Θέση</span></div><div class=\"lab-row\"><span class=\"lab-name\">Αιμοσφαιρίνη</span><span class=\"lab-val ok\">11,8 g/dL</span><span class=\"lab-ref\">11,7–15,7 g/dL</span><span class=\"lab-track\"><span class=\"lab-band\" style=\"left:27.3%;width:45.5%\"></span><span class=\"lab-mark ok\" style=\"left:28.4%\"></span></span></div><div class=\"lab-row\"><span class=\"lab-name\">Μέσος όγκος ερυθρών (MCV)</span><span class=\"lab-val ok\">85 fL</span><span class=\"lab-ref\">80–99 fL</span><span class=\"lab-track\"><span class=\"lab-band\" style=\"left:27.3%;width:45.5%\"></span><span class=\"lab-mark ok\" style=\"left:39.2%\"></span></span></div><div class=\"lab-row abn\"><span class=\"lab-name\">Λευκά αιμοσφαίρια (WBC)</span><span class=\"lab-val high\">15,6 × 10⁷/L<b>↑</b></span><span class=\"lab-ref\">3,5–11,0 × 10⁷/L</span><span class=\"lab-track\"><span class=\"lab-band\" style=\"left:25.4%;width:42.3%\"></span><span class=\"lab-mark high\" style=\"left:93.7%\"></span></span></div><div class=\"lab-row\"><span class=\"lab-name\">Αιμοπετάλια</span><span class=\"lab-val ok\">235 × 10⁷/L</span><span class=\"lab-ref\">150–440 × 10⁷/L</span><span class=\"lab-track\"><span class=\"lab-band\" style=\"left:27.3%;width:45.5%\"></span><span class=\"lab-mark ok\" style=\"left:40.6%\"></span></span></div><div class=\"lab-row abn\"><span class=\"lab-name\">C-αντιδρώσα πρωτεΐνη (CRP)</span><span class=\"lab-val high\">56 mg/L<b>↑</b></span><span class=\"lab-ref\">&lt;5 mg/L</span><span class=\"lab-track\"><span class=\"lab-band\" style=\"left:2.2%;width:3.7%\"></span><span class=\"lab-mark high\" style=\"left:99.4%\"></span></span></div></div><figure class=\"case-fig\"><img src=\"assets/images/case_36_1.jpg\" alt=\"Βαριούχος υποκλυσμός\" loading=\"lazy\" onerror=\"this.closest('.case-fig').classList.add('no-img')\"><div class=\"fig-ph\"><b>assets/images/case_36_1.jpg</b>Τοποθετήστε εδώ την εικόνα.</div><figcaption><b>Εικόνα 36.1</b> · Βαριούχος υποκλυσμός</figcaption></figure>",
